('a0000000-0000-0000-0000-000000000001', 'Photorealistic AI Sci-Fi & Cyberpunk Filmmaker', 'Former VFX Supervisor with 8 years in Hollywood turned generative AI director. Specializes in photorealistic cinematic commercials and narrative teasers using Midjourney v6, Sora, and Runway Gen-3.', 'Los Angeles, CA', 'AI Filmmaking & VFX', ARRAY['Cinematic Lighting', 'Prompt Architecture', 'Camera Motion Control', 'Color Grading'], ARRAY['Midjourney v6', 'Runway Gen-3', 'Sora', 'ComfyUI', 'Topaz Video AI'], ARRAY['Video Commercials', 'Movie Teasers', 'Brand Anthems'], ARRAY['Photorealistic', 'Cyberpunk', 'Cinematic Noir'], 150, 1100, 'Available Now', '2-4 days', 4.98),

('a0000000-0000-0000-0000-000000000002', 'Hyper-Realistic Commercial & Fashion Generative Director', 'Creative Director helping global luxury brands create ultra-refined product ads using Flux.1 and Luma Dream Machine.', 'New York, NY', 'Fashion & Product Ads', ARRAY['Luxury Aesthetic', 'Texture Synthesis', 'Model Consistency', 'Sound Design'], ARRAY['Flux.1', 'Luma Dream Machine', 'Midjourney v6', 'Photoshop AI'], ARRAY['Social Ads', 'Product Trailers', 'Lookbooks'], ARRAY['Hyper-Realistic', 'Minimalist Luxury', 'High Fashion'], 180, 1300, 'Available Now', '3-5 days', 4.95),

