-- Portfolio Items with Detailed Workflows
INSERT INTO public.portfolio_items (creator_id, title, description, media_url, media_type, thumbnail_url, tools_used, prompt_summary, workflow_steps, aspect_ratio, duration, resolution, tags, verification_status) VALUES
('a0000000-0000-0000-0000-000000000001', 'Neon Horizon 2099 - Cyberpunk Speeder Commercial', 'A 30-second hyper-realistic teaser showing an autonomous hovercraft speeding through neon rain in Neo-Tokyo.', 'https://images.unsplash.com/photo-1508739773434-c26b3d09e071?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1508739773434-c26b3d09e071?w=600&h=337&fit=crop', ARRAY['Midjourney v6', 'Runway Gen-3', 'ComfyUI', 'Topaz Video AI'], 'Cinematic 8k shot of sleek obsidian speeder gliding through wet neon rain cityscape, volumetric fog, anamorphic lens flare --ar 16:9 --style raw', ARRAY['1. Prompt iteration in Midjourney v6 for base keyframes', '2. Frame enhancement and ControlNet depth mapping in ComfyUI', '3. Video motion generation in Runway Gen-3 with custom camera pan prompt', '4. 4K 60fps interpolation in Topaz Video AI'], '16:9', '0:30', '4K UHD', ARRAY['Cyberpunk', 'Sci-Fi', 'Commercial', 'Anamorphic'], 'verified_creator'),

('a0000000-0000-0000-0000-000000000002', 'Aether Silk - Luxury Perfume Reveal', 'Minimalist visual launch campaign featuring floating glass perfume bottles with organic silk wave physics.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?w=600&h=337&fit=crop', ARRAY['Flux.1', 'Luma Dream Machine', 'Photoshop AI'], 'Haute couture perfume bottle floating amidst liquid gold silk, studio refraction lighting, soft focus bokeh --ar 16:9', ARRAY['1. Flux.1 Schnell prompt for crystal glass material synthesis', '2. Multi-angle lighting rendering using Luma Dream Machine', '3. Color grading and macro detail enhancement in Photoshop AI'], '16:9', '0:20', '4K UHD', ARRAY['Luxury', 'Perfume', 'Fashion', 'Minimalist'], 'verified_creator'),

('a0000000-0000-0000-0000-000000000003', 'Bio-Luminescent Abyss', 'Surrealist motion piece exploring organic underwater structures emitting pulse light.', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600&h=337&fit=crop', ARRAY['Kling AI', 'Stable Diffusion XL', 'Blender AI'], 'Surreal alien coral organism pulsing with iridescent violet light in deep navy water, macro shot --ar 16:9', ARRAY['1. SDXL base generation with custom LoRA fine-tuned on marine life', '2. Kling AI camera zoom & fluid animation', '3. Blender AI volumetric lighting pass'], '16:9', '0:45', '1080p HD', ARRAY['Surreal', '3D Animation', 'Organic', 'Music Video'], 'community_verified'),

('a0000000-0000-0000-0000-000000000004', 'Phantom Velocity - Anime Racing Opener', 'High-energy hand-drawn style anime sequence featuring stylized sports car drift.', 'https://images.unsplash.com/photo-1542282088-72c9c27ed0cd?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1542282088-72c9c27ed0cd?w=600&h=337&fit=crop', ARRAY['AnimateDiff', 'ControlNet', 'Flux.1'], 'Dynamic action anime aesthetic, sports car drifting through neon highway, speed lines, high contrast cel shading --ar 16:9', ARRAY['1. Pose skeleton creation in Blender', '2. ControlNet lineart conditioning in AnimateDiff', '3. Post-processing frame cleanup in Premiere Pro'], '16:9', '0:15', '4K UHD', ARRAY['Anime', 'Action', 'Cell Shaded', 'VFX'], 'verified_creator'),

('a0000000-0000-0000-0000-000000000005', 'Villa Celestia - Architectural Showcase', 'Photorealistic walkthrough of a cliffside modern villa in Santorini under sunset dusk lighting.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=600&h=337&fit=crop', ARRAY['Midjourney v6', 'Runway Gen-3', 'Magnific AI'], 'Architectural photography of modern glass infinity villa on Aegean cliff, golden hour light, architecturaldigest style --ar 16:9', ARRAY['1. Midjourney v6 architectural prompt composition', '2. Magnific AI 8K texture upscale', '3. Runway Gen-3 drone camera motion trajectory'], '16:9', '0:40', '4K UHD', ARRAY['Architecture', 'Real Estate', 'Luxury', 'Photorealistic'], 'self_reported'),

('a0000000-0000-0000-0000-000000000007', 'Pulse Runner 9:16 Social Teaser', 'Vertical viral sneaker teaser optimized for Instagram Reels with dynamic glitch transitions.', 'https://images.unsplash.com/photo-1552346154-21d32810aba3?w=675&h=1200&fit=crop', 'image', 'https://images.unsplash.com/photo-1552346154-21d32810aba3?w=337&h=600&fit=crop', ARRAY['Luma Dream Machine', 'Flux.1', 'After Effects'], 'Futuristic glowing running shoe assembling from digital energy particles, extreme vertical 9:16 format', ARRAY['1. Flux.1 shoe render in portrait aspect ratio', '2. Luma Dream Machine camera roll and particle effect', '3. AE sound design and kinetic typography overlay'], '9:16', '0:15', '1080p HD', ARRAY['Instagram Reels', 'Sneaker', 'Social Ad', 'Vertical'], 'verified_creator'),

('a0000000-0000-0000-0000-000000000010', 'Hyperion GT - Electric Supercar Reveal', 'Studio setup and racetrack action scenes for an unreleased concept electric GT car.', 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?w=1200&h=675&fit=crop', 'image', 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?w=600&h=337&fit=crop', ARRAY['Midjourney v6', 'Luma Dream Machine', 'DaVinci Resolve'], 'Matte dark red electric supercar on wet asphalt under stadium lights, realistic brake disc glow, cinematic panning camera --ar 16:9', ARRAY['1. Vehicle design prompt tuning in Midjourney', '2. Racetrack motion generation in Luma', '3. DaVinci Resolve custom HDR color grade and engine audio sync'], '16:9', '0:30', '4K UHD', ARRAY['Automotive', 'Supercar', 'Commercial', 'High Speed'], 'verified_creator');

