INSERT INTO public.briefs (id, brand_id, title, objective, description, target_audience, content_type, style, tone, aspect_ratio, duration, resolution, deliverables, preferred_tools, required_skills, budget, currency, deadline, status) VALUES
('b0000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', 'Futuristic Sneaker Launch Video', 'Launch the Aether-V9 self-lacing cyber sneaker with a 30-second high-impact vertical video for Instagram Reels & TikTok.', 'We are looking for an AI visual artist to produce a sleek, photorealistic 30-second cyber-aesthetic commercial for our new footwear line. The video should showcase synthetic footwear assembling in mid-air with volumetric glow.', 'Gen Z & Millennial sneakerheads, tech enthusiasts aged 18-35', 'Social Media Commercial', 'Cyberpunk / Photorealistic', 'Energetic, High-Tech, Premium', '9:16', '0:30', '4K UHD', ARRAY['1x Vertical Master (9:16)', '1x Square Cutdown (1:1)', 'Prompt & Source Assets'], ARRAY['Flux.1', 'Runway Gen-3', 'Luma Dream Machine'], ARRAY['3D Motion Synthesis', 'High-Speed Particle Effects', 'Color Grading'], 3500, 'USD', '2026-11-15', 'published'),

('b0000000-0000-0000-0000-000000000002', '22222222-2222-2222-2222-222222222222', 'Organic Energy Drink Commercial', 'Create a 15-second cinematic landscape commercial showcasing nature meeting futuristic bio-tech.', 'Seeking an AI animator to craft a vibrant, organic surrealist clip of glowing botanical ingredients dissolving into a sleek liquid can under pristine daylight.', 'Health-conscious professionals and fitness creators aged 22-40', 'Brand Anthem Video', 'Organic Bio / Surrealist', 'Refreshing, Inspiring, High-End', '16:9', '0:15', '4K UHD', ARRAY['1x Landscape Master (16:9)', 'Layered Audio Track'], ARRAY['Midjourney v6', 'Kling AI', 'Topaz Video AI'], ARRAY['Fluid Physics AI', 'Photorealistic Lighting', 'Macro Detail'], 2800, 'USD', '2026-11-20', 'published'),

('b0000000-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'Luxury Watch Teaser Campaign', 'Produce a series of 3 macro luxury timepiece visualizers with raytraced glass and gold reflections.', 'We require a creator specialized in luxury product renders to generate macro motion clips of clockwork mechanisms evolving into a constellation.', 'High-net-worth collectors & fashion directors', 'Product Launch Teaser', 'Minimalist Luxury', 'Sophisticated, Elegant, Mysterious', '16:9', '0:45', '4K UHD', ARRAY['3x 15-second Video Teasers', 'High-Res Still Keyframes'], ARRAY['Flux.1', 'Magnific AI', 'DaVinci Resolve'], ARRAY['Texture Synthesis', 'Macro Lighting', 'Consistent Geometry'], 5000, 'USD', '2026-12-01', 'published')
ON CONFLICT (id) DO NOTHING;

